// SetLogic replaces the registered business logic for this record only (tests); no
// arguments runs no triggers at all.
func (t *Project) SetLogic(logic ...any) {
	for _, l := range logic {
		checkLogic(ProjectTableName, "Project", l, projectTrigger)
	}
	if logic == nil {
		logic = []any{}
	}
	t.logic = logic
}

func (t *Project) registeredLogic() []any {
	if t.logic != nil {
		return t.logic
	}
	return projectLogic
}

