// FindSet opens a result set matching current filters
// Call Next() to iterate through the results
// Returns true if at least one record found, false otherwise
func (t *Project) FindSet() bool {
	// A temporary record, and a record in a transaction, reads all at once: its in-memory
	// database or the transaction has one connection, which an open result set would block for
	// the statements of the loop (Modify while looping; on PostgreSQL a query while the rows are
	// read breaks the connection — "unexpected Parse response")
	if _, inTx := t.db.(*sql.Tx); t.temp != nil || inTx {
		return t.FindSetBuffered()
	}
	// Close any existing result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}
	t.bufferedRecords = nil
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, search_description, description, description_2, bill_to_customer_no, creation_date, starting_date, ending_date, completion_date, project_posting_date, recognition_date, completion_percent, status, person_responsible, dimension_1_code, dimension_2_code, project_posting_group, blocked, recognition_method, last_date_modified, application_method, project_usage_posting, picture, no_series FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Project: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
}

// Next advances to the next record: in the result set after FindSet() or FindSetBuffered(),
// else from the current record in the current key (after Get, Find, FindFirst, FindLast)
// Optional steps parameter:
//   - Next() or Next(1): Move forward 1 record (default)
//   - Next(5): Skip forward 5 records
//   - Next(-1): Move backward 1 record (FindSetBuffered, or after Get/Find)
//   - Next(-3): Skip backward 3 records (FindSetBuffered, or after Get/Find)
//
// Returns true if a record was loaded, false if no more records or out of bounds
func (t *Project) Next(steps ...int) bool {
	// Default to 1 step forward
	step := 1
	if len(steps) > 0 {
		step = steps[0]
	}

	// BUFFERED MODE: Bidirectional navigation with in-memory records
	if t.bufferedRecords != nil {
		// Calculate new position
		newPos := t.currentBufferPos + step

		// Check bounds
		if newPos < 0 || newPos >= len(t.bufferedRecords) {
			return false // Out of bounds
		}

		// Move to new position
		t.currentBufferPos = newPos
		t.copyFromBuffered(t.bufferedRecords[t.currentBufferPos])
		return true
	}

	// FORWARD-ONLY MODE: Streaming with sql.Rows (only positive steps allowed)
	if t.currentRows != nil {
		// Validate: only forward movement allowed
		if step < 1 {
			fmt.Printf("Error: Backward navigation (Next(%d)) requires FindSetBuffered()\n", step)
			return false
		}

		// Advance 'step' times (1 = next record, 2 = skip 1 record, etc.)
		for i := 0; i < step; i++ {
			if !t.currentRows.Next() {
				// No more rows - close result set
				t.currentRows.Close()
				t.currentRows = nil
				return false
			}
		}

		// Scan the row
		var noNull sql.NullString
		var search_descriptionNull sql.NullString
		var descriptionNull sql.NullString
		var description_2Null sql.NullString
		var bill_to_customer_noNull sql.NullString
		var creation_dateNull sql.NullString
		var starting_dateNull sql.NullString
		var ending_dateNull sql.NullString
		var completion_dateNull sql.NullString
		var project_posting_dateNull sql.NullString
		var recognition_dateNull sql.NullString
		var completion_percentNull sql.NullString
		var statusInt int
		var person_responsibleNull sql.NullString
		var dimension_1_codeNull sql.NullString
		var dimension_2_codeNull sql.NullString
		var project_posting_groupNull sql.NullString
		var blockedBool sql.NullBool
		var recognition_methodInt int
		var last_date_modifiedNull sql.NullString
		var application_methodInt int
		var project_usage_postingInt int
		var no_seriesNull sql.NullString

		err := t.currentRows.Scan(
			&noNull,
			&search_descriptionNull,
			&descriptionNull,
			&description_2Null,
			&bill_to_customer_noNull,
			&creation_dateNull,
			&starting_dateNull,
			&ending_dateNull,
			&completion_dateNull,
			&project_posting_dateNull,
			&recognition_dateNull,
			&completion_percentNull,
			&statusInt,
			&person_responsibleNull,
			&dimension_1_codeNull,
			&dimension_2_codeNull,
			&project_posting_groupNull,
			&blockedBool,
			&recognition_methodInt,
			&last_date_modifiedNull,
			&application_methodInt,
			&project_usage_postingInt,
			&t.Picture,
			&no_seriesNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Project record: %v\n", err)
			t.currentRows.Close()
			t.currentRows = nil
			return false
		}

		// Populate fields
		t.No = types.NewCode(noNull.String)
		t.Search_description = types.NewCode(search_descriptionNull.String)
		t.Description = types.NewText(descriptionNull.String)
		t.Description_2 = types.NewText(description_2Null.String)
		t.Bill_to_customer_no = types.NewCode(bill_to_customer_noNull.String)
		t.Creation_date, _ = types.NewDateFromString(creation_dateNull.String)
		t.Starting_date, _ = types.NewDateFromString(starting_dateNull.String)
		t.Ending_date, _ = types.NewDateFromString(ending_dateNull.String)
		t.Completion_date, _ = types.NewDateFromString(completion_dateNull.String)
		t.Project_posting_date, _ = types.NewDateFromString(project_posting_dateNull.String)
		t.Recognition_date, _ = types.NewDateFromString(recognition_dateNull.String)
		t.Completion_percent, _ = types.NewDecimalFromString(completion_percentNull.String)
		t.Status = ProjectStatus(statusInt)
		t.Person_responsible = types.NewCode(person_responsibleNull.String)
		t.Dimension_1_code = types.NewCode(dimension_1_codeNull.String)
		t.Dimension_2_code = types.NewCode(dimension_2_codeNull.String)
		t.Project_posting_group = types.NewCode(project_posting_groupNull.String)
		t.Blocked = blockedBool.Bool
		t.Recognition_method = ProjectRecognition_method(recognition_methodInt)
		t.Last_date_modified, _ = types.NewDateFromString(last_date_modifiedNull.String)
		t.Application_method = ProjectApplication_method(application_methodInt)
		t.Project_usage_posting = ProjectProject_usage_posting(project_usage_postingInt)
		t.No_series = types.NewCode(no_seriesNull.String)

		// Store old values for field tracking
		t.StoreOldValues()

		return true
	}

	// No record set (after Get, Find, FindFirst, FindLast): the next record in the current key
	// and direction within the filters, one step at a time (classic NEXT after FIND); a step
	// that finds none leaves the record on the last one reached
	if step == 0 {
		return false
	}
	for i := 0; i != step; {
		if step > 0 {
			if !t.findInKey(">", false) {
				return false
			}
			i++
		} else {
			if !t.findInKey("<", true) {
				return false
			}
			i--
		}
	}
	return true
}

// FindSetBuffered loads all filtered records into memory for bidirectional navigation
// Use this when you need to move backward/forward with Next(steps)
// Filters (SetRange/SetFilter) are applied in SQL before buffering to minimize memory usage
// Returns true if at least one record found, false otherwise
func (t *Project) FindSetBuffered() bool {
	// Close any existing forward-only result set
	if t.currentRows != nil {
		t.currentRows.Close()
		t.currentRows = nil
	}

	// Clear any existing buffer
	t.bufferedRecords = nil
	t.currentBufferPos = -1
	tableName := fmt.Sprintf("%s$%s", t.company, ProjectTableName)
	where, args := t.buildWhereClause()
	orderBy, orderArgs := t.getOrderByClause()
	args = append(args, orderArgs...)

	// Build SELECT with all fields
	query := fmt.Sprintf(`SELECT no, search_description, description, description_2, bill_to_customer_no, creation_date, starting_date, ending_date, completion_date, project_posting_date, recognition_date, completion_percent, status, person_responsible, dimension_1_code, dimension_2_code, project_posting_group, blocked, recognition_method, last_date_modified, application_method, project_usage_posting, picture, no_series FROM "%s" WHERE %s ORDER BY %s%s`, tableName, where, orderBy, t.getLimitClause())

	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSetBuffered for Project: %v\n", err)
		return false
	}
	defer rows.Close()

	// Load all records into memory
	for rows.Next() {
		// Create a new record instance
		record := &Project{}
		record.db = t.db
		record.temp = t.temp
		record.company = t.company
		record.dbType = t.dbType

		// Scan the row
		var noNull sql.NullString
		var search_descriptionNull sql.NullString
		var descriptionNull sql.NullString
		var description_2Null sql.NullString
		var bill_to_customer_noNull sql.NullString
		var creation_dateNull sql.NullString
		var starting_dateNull sql.NullString
		var ending_dateNull sql.NullString
		var completion_dateNull sql.NullString
		var project_posting_dateNull sql.NullString
		var recognition_dateNull sql.NullString
		var completion_percentNull sql.NullString
		var statusInt int
		var person_responsibleNull sql.NullString
		var dimension_1_codeNull sql.NullString
		var dimension_2_codeNull sql.NullString
		var project_posting_groupNull sql.NullString
		var blockedBool sql.NullBool
		var recognition_methodInt int
		var last_date_modifiedNull sql.NullString
		var application_methodInt int
		var project_usage_postingInt int
		var no_seriesNull sql.NullString

		err := rows.Scan(
			&noNull,
			&search_descriptionNull,
			&descriptionNull,
			&description_2Null,
			&bill_to_customer_noNull,
			&creation_dateNull,
			&starting_dateNull,
			&ending_dateNull,
			&completion_dateNull,
			&project_posting_dateNull,
			&recognition_dateNull,
			&completion_percentNull,
			&statusInt,
			&person_responsibleNull,
			&dimension_1_codeNull,
			&dimension_2_codeNull,
			&project_posting_groupNull,
			&blockedBool,
			&recognition_methodInt,
			&last_date_modifiedNull,
			&application_methodInt,
			&project_usage_postingInt,
			&record.Picture,
			&no_seriesNull,
		)

		if err != nil {
			fmt.Printf("Error: Failed to scan Project record: %v\n", err)
			return false
		}

		// Populate special type fields
		record.No = types.NewCode(noNull.String)
		record.Search_description = types.NewCode(search_descriptionNull.String)
		record.Description = types.NewText(descriptionNull.String)
		record.Description_2 = types.NewText(description_2Null.String)
		record.Bill_to_customer_no = types.NewCode(bill_to_customer_noNull.String)
		record.Creation_date, _ = types.NewDateFromString(creation_dateNull.String)
		record.Starting_date, _ = types.NewDateFromString(starting_dateNull.String)
		record.Ending_date, _ = types.NewDateFromString(ending_dateNull.String)
		record.Completion_date, _ = types.NewDateFromString(completion_dateNull.String)
		record.Project_posting_date, _ = types.NewDateFromString(project_posting_dateNull.String)
		record.Recognition_date, _ = types.NewDateFromString(recognition_dateNull.String)
		record.Completion_percent, _ = types.NewDecimalFromString(completion_percentNull.String)
		record.Status = ProjectStatus(statusInt)
		record.Person_responsible = types.NewCode(person_responsibleNull.String)
		record.Dimension_1_code = types.NewCode(dimension_1_codeNull.String)
		record.Dimension_2_code = types.NewCode(dimension_2_codeNull.String)
		record.Project_posting_group = types.NewCode(project_posting_groupNull.String)
		record.Blocked = blockedBool.Bool
		record.Recognition_method = ProjectRecognition_method(recognition_methodInt)
		record.Last_date_modified, _ = types.NewDateFromString(last_date_modifiedNull.String)
		record.Application_method = ProjectApplication_method(application_methodInt)
		record.Project_usage_posting = ProjectProject_usage_posting(project_usage_postingInt)
		record.No_series = types.NewCode(no_seriesNull.String)

		// Store old values
		record.StoreOldValues()

		// Add to buffer
		t.bufferedRecords = append(t.bufferedRecords, record)
	}

	// Check for errors during iteration
	if err := rows.Err(); err != nil {
		fmt.Printf("Error: Failed to iterate Project records: %v\n", err)
		return false
	}

	// If no records found, return false
	if len(t.bufferedRecords) == 0 {
		return false
	}

	// Load first record into current instance
	t.currentBufferPos = 0
	t.copyFromBuffered(t.bufferedRecords[0])

	return true
}

