// SetFlowFilter sets a FlowFilter field's filter expression (SETFILTER on a
// FlowFilter field); FlowFields applying it use it from then on. "" clears it.
func (t *Project) SetFlowFilter(field, expr string) error {
	switch field {
	case "type_filter":
		if err := flowfilter.Validate(flowfilter.KindInt, expr); err != nil {
			return err
		}
		t.Type_filter = expr
		return nil
	case "resource_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Resource_filter = expr
		return nil
	case "date_filter":
		if err := flowfilter.Validate(flowfilter.KindDate, expr); err != nil {
			return err
		}
		t.Date_filter = expr
		return nil
	case "phase_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Phase_filter = expr
		return nil
	case "task_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Task_filter = expr
		return nil
	case "step_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Step_filter = expr
		return nil
	case "resource_gr_filter":
		if err := flowfilter.Validate(flowfilter.KindCode, expr); err != nil {
			return err
		}
		t.Resource_gr_filter = expr
		return nil
	}
	return fmt.Errorf("%q is not a FlowFilter field of Project", field)
}

